"""Live local cap footprints from four certified ordered boundary records.

The cut lies within the first physical segment of every boundary at the chosen
end, no farther than Maximum Depth beyond their latest endpoint. That condition
is checked, not assumed. A wider or curved cap requires a
different polygon provider. Coordinates passed to the union primitive use a
local frame aligned with the inward Axis. All cut corners share exactly Cut as
their local X coordinate, avoiding independent roundoff at coincident edges.
World positions are Origin + x * Frame X + y * Frame Y. The inverse frame
accounts for float-normalized axes whose squared length is not exactly one.
Source boundary positions are never changed.
"""
import bpy
from .path_surface_nodes import _Nodes
from . import bundle_axis_nodes as axis, bundle_cap_outline_nodes as outline

NAME='Prochitecture Streets / Live linear Bundle end caps v1'


def _pick(g,index,values):
    node=g.node('GeometryNodeIndexSwitch','Cyclic physical cap corners');node.data_type='VECTOR'
    node.index_switch_items.clear()
    for _ in values:node.index_switch_items.new()
    g.set(index,node.inputs['Index'])
    for socket,value in zip(list(node.inputs)[1:],values):g.set(value,socket)
    return node.outputs[0]


def build(*, narrow_fill=False, finite_contact=False):
    if finite_contact and not narrow_fill:
        raise ValueError('Finite contact caps require the narrow-infill interface')
    group_name=NAME+' / narrow paved infill v1' if narrow_fill else NAME
    if finite_contact:group_name+=' / finite inner contact v1'
    existing=bpy.data.node_groups.get(group_name)
    if existing:return existing
    tree=bpy.data.node_groups.new(group_name,'GeometryNodeTree');g=_Nodes(tree)
    for k in range(4):tree.interface.new_socket(name='Boundary '+str(k),in_out='INPUT',socket_type='NodeSocketGeometry')
    tree.interface.new_socket(name='Axis',in_out='INPUT',socket_type='NodeSocketVector').default_value=(1.,0.,0.)
    tree.interface.new_socket(name='At End',in_out='INPUT',socket_type='NodeSocketBool')
    tree.interface.new_socket(name='Maximum Depth',in_out='INPUT',socket_type='NodeSocketFloat').default_value=.5
    if narrow_fill:
        tree.interface.new_socket(name='Minimum Separator Width',in_out='INPUT',socket_type='NodeSocketFloat').default_value=.12
    for name,kind in (('Geometry','Geometry'),('Cap A','Geometry'),('Cap B','Geometry'),
                      ('Origin','Vector'),('Frame X','Vector'),('Frame Y','Vector'),
                      ('Outer A','Vector'),('Outer B','Vector'),('Cut A','Vector'),('Cut B','Vector'),
                      ('Inner Cut A','Vector'),('Inner Cut B','Vector'),
                      ('Cut','Float'),('Cut Valid','Bool'),('Valid','Bool')):
        tree.interface.new_socket(name=name,in_out='OUTPUT',socket_type='NodeSocket'+kind)
    if narrow_fill:
        tree.interface.new_socket(name='Narrow Filled',in_out='OUTPUT',socket_type='NodeSocketBool')
        for k in range(4):
            for prefix in ('Local End ','Physical End '):
                tree.interface.new_socket(name=prefix+str(k),in_out='OUTPUT',socket_type='NodeSocketVector')
    inp=g.node('NodeGroupInput','Four live certified member boundary records')
    out=g.node('NodeGroupOutput','Local cap footprints and shared union outline')
    index=g.node('GeometryNodeInputIndex','Cap corner index').outputs[0]
    physical=g.node('GeometryNodeInputNamedAttribute','Actual certified physical boundary positions')
    physical.data_type='FLOAT_VECTOR';physical.inputs['Name'].default_value='st_axis_xy'
    first=[];adjacent=[];checks=[]
    for k in range(4):
        source=inp.outputs['Boundary '+str(k)];count=axis._size(g,source)
        endpoint=g.switch(inp.outputs['At End'],0,g.math('SUBTRACT',count,1.),'INT')
        neighbor=g.switch(inp.outputs['At End'],1,g.math('SUBTRACT',count,2.),'INT')
        first.append(g.sample(source,physical.outputs['Attribute'],endpoint,'FLOAT_VECTOR'))
        adjacent.append(g.sample(source,physical.outputs['Attribute'],neighbor,'FLOAT_VECTOR'))
        checks.extend((g.compare(count,2,'GREATER_EQUAL','INT'),
                       g.sample(source,physical.outputs['Exists'],0,'BOOLEAN')))
    origin=g.vector('SCALE',g.vector('ADD',first[0],first[3]),.5)
    direction=g.vector('NORMALIZE',g.xyz(g.component(inp.outputs['Axis'],'X'),g.component(inp.outputs['Axis'],'Y')))
    direction=g.vector('SCALE',direction,g.switch(inp.outputs['At End'],1.,-1.))
    lateral=g.vector('CROSS_PRODUCT',(0.,0.,1.),direction)
    inverse_norm=g.math('DIVIDE',1.,g.vector('DOT_PRODUCT',direction,direction))
    checks.append(g.compare(g.vector('LENGTH',direction),.99,'GREATER_THAN'))
    physical_first=first
    first=[g.vector('SUBTRACT',p,origin) for p in first]
    adjacent=[g.vector('SUBTRACT',p,origin) for p in adjacent]
    for p in first+adjacent:
        checks.append(g.close(g.component(p,'Z'),0.,outline.EPS))
    first=[g.xyz(g.vector('DOT_PRODUCT',p,direction),g.vector('DOT_PRODUCT',p,lateral)) for p in first]
    adjacent=[g.xyz(g.vector('DOT_PRODUCT',p,direction),g.vector('DOT_PRODUCT',p,lateral)) for p in adjacent]
    begin=[g.component(p,'X') for p in first]
    following=[g.component(p,'X') for p in adjacent]
    low=begin[0];high=following[0]
    for value in begin[1:]:low=g.math('MAXIMUM',low,value)
    for value in following[1:]:high=g.math('MINIMUM',high,value)
    checks.append(g.compare(g.math('SUBTRACT',high,low),outline.JOIN_ALLOWANCE,'GREATER_THAN'))
    checks.append(g.compare(inp.outputs['Maximum Depth'],outline.JOIN_ALLOWANCE,'GREATER_THAN'))
    depth=g.math('MINIMUM',inp.outputs['Maximum Depth'],g.math('MULTIPLY',.5,g.math('SUBTRACT',high,low)))
    cut=g.math('ADD',low,depth)
    clipped=[]
    for p,q,a,b in zip(first,adjacent,begin,following):
        checks.append(g.compare(g.math('SUBTRACT',b,a),outline.JOIN_ALLOWANCE,'GREATER_THAN'))
        fraction=g.math('DIVIDE',g.math('SUBTRACT',cut,a),g.math('SUBTRACT',b,a))
        y=g.math('ADD',g.component(p,'Y'),g.math('MULTIPLY',fraction,
            g.math('SUBTRACT',g.component(q,'Y'),g.component(p,'Y'))))
        clipped.append(g.xyz(cut,y))
    cap_call=g.node('GeometryNodeGroup','Shared exposed member-cap union boundary');cap_call.node_tree=outline.build()
    for i,name in ((0,'Cap A'),(2,'Cap B')):
        corners=(first[i],clipped[i],clipped[i+1],first[i+1])
        turn=g.vector('CROSS_PRODUCT',g.vector('SUBTRACT',corners[1],corners[0]),
                      g.vector('SUBTRACT',corners[2],corners[1]))
        ccw=g.compare(g.component(turn,'Z'),0.,'GREATER_THAN')
        corners=[g.switch(ccw,b,a,'VECTOR') for a,b in zip(corners,reversed(corners))]
        line=g.node('GeometryNodeMeshLine','Four '+name+' control corners');line.inputs['Count'].default_value=4
        positioned=g.node('GeometryNodeSetPosition','Actual '+name+' linear end footprint')
        g.set(line.outputs['Mesh'],positioned.inputs['Geometry']);g.set(_pick(g,index,corners),positioned.inputs['Position'])
        g.set(positioned.outputs['Geometry'],cap_call.inputs[name]);g.set(positioned.outputs['Geometry'],out.inputs[name])
    cut_valid=g.all(*checks)
    valid=g.all(cut_valid,cap_call.outputs['Valid'])
    geometry=cap_call.outputs['Geometry']
    if narrow_fill:
        from . import bundle_narrow_cap_nodes
        infill,infill_valid=bundle_narrow_cap_nodes.construct(g,first,clipped,inp.outputs['Minimum Separator Width'],
                                                           finite_contact=finite_contact)
        geometry=g.switch(infill_valid,geometry,infill,'GEOMETRY')
        valid=g.all(cut_valid,g.either(cap_call.outputs['Valid'],infill_valid))
        g.set(g.all(cut_valid,infill_valid),out.inputs['Narrow Filled'])
        for k in range(4):
            g.set(first[k],out.inputs['Local End '+str(k)])
            g.set(physical_first[k],out.inputs['Physical End '+str(k)])
    g.set(g.switch(valid,None,geometry,'GEOMETRY'),out.inputs['Geometry'])
    for name,value in (('Origin',origin),('Cut',cut),('Valid',valid),
                       ('Outer A',first[0]),('Outer B',first[3]),('Cut A',clipped[0]),('Cut B',clipped[3]),
                       ('Inner Cut A',clipped[1]),('Inner Cut B',clipped[2]),('Cut Valid',cut_valid),
                       ('Frame X',g.vector('SCALE',direction,inverse_norm)),
                       ('Frame Y',g.vector('SCALE',lateral,inverse_norm))):g.set(value,out.inputs[name])
    return tree
